import sys

def parse_endpoints(lines):
    """Parse ENDPOINTS section. Stop at first malformed line."""
    endpoints = []
    for line in lines:
        line = line.strip()
        if not line:
            break
        parts = line.split()
        if len(parts) != 4:
            break
        path, method, role, permission = parts
        if not path:
            break
        method = method.upper()
        permission = permission.upper()
        if method not in ("GET", "POST", "PUT", "DELETE", "PATCH"):
            break
        if permission not in ("ALLOW", "DENY"):
            break
        if not role.strip():
            break
        endpoints.append({
            "path": path,
            "method": method,
            "role": role,
            "permission": permission
        })
    return endpoints

def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section."""
    base = None
    exclude = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "base":
            if len(parts) == 2:
                base = parts[1]
        elif parts[0] == "exclude":
            if len(parts) >= 2:
                exclude = parts[1:]
    return base, exclude

def parse_plan(lines):
    """Parse PLAN section. Stop at first malformed line."""
    plan = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if not path:
            break
        method = method.upper()
        if method not in ("GET", "POST", "PUT", "DELETE", "PATCH"):
            break
        plan.append({
            "path": path,
            "method": method
        })
    return plan

def normalize_path_for_matching(path):
    """Replace {variable_name} with {var} for matching purposes."""
    result = []
    i = 0
    while i < len(path):
        if path[i] == '{':
            j = i + 1
            while j < len(path) and path[j] not in '}' and path[j] not in ' 	':
                j += 1
            if j < len(path) and path[j] == '}':
                result.append('{var}')
                i = j + 1
            else:
                result.append(path[i:j])
                i = j
        else:
            result.append(path[i])
            i += 1
    return ''.join(result)

def get_variable_name(path):
    """Extract the first variable name from {variable_name} pattern."""
    for i in range(len(path)):
